#include <zephyr/json/json.h>
#include <zephyr/sys/byteorder.h>
#include <zephyr/logging/log.h>
#include <string.h>
#include <stdio.h>

LOG_MODULE_REGISTER(json, CONFIG_JSON_LOG_LEVEL);

#define JSON_TOKEN_BUF_SIZE (CONFIG_JSON_TOKEN_COUNT * sizeof(struct json_token))

/*
 * The JSON library uses a single global buffer for tokens. This is fine for
 * single-threaded applications, but for multi-threaded applications, this
 * means that only one thread can parse JSON at a time. If multiple threads
 * try to parse JSON simultaneously, the token buffer will be corrupted.
 *
 * To fix this, we use a K_THREAD_LOCAL token buffer. This ensures that each
 * thread has its own token buffer, so multiple threads can parse JSON
 * simultaneously without corrupting the token buffer.
 *
 * This is a temporary solution until the JSON library is refactored to use
 * a more robust token buffer management strategy.
 */
#ifdef CONFIG_MULTITHREADING
K_THREAD_LOCAL
#endif
static struct json_token tokens[CONFIG_JSON_TOKEN_COUNT];

static int json_next_token(const char *json_string, size_t len,
			   struct json_token *tokens, size_t tokens_count,
			   size_t *token_idx)
{
	int r;

	if (*token_idx >= tokens_count) {
		return -ENOMEM;
	}

	r = json_parse_token(json_string, len, &tokens[*token_idx]);
	if (r < 0) {
		return r;
	}

	return 0;
}

static int json_token_is_string(const char *json_string, const struct json_token *token,
				const char *str)
{
	if (token->type != JSON_TOK_STRING) {
		return 0;
	}

	return json_token_cmp(json_string, token, str);
}

static int json_obj_parse_internal(const char *json_string, size_t len,
				   const struct json_obj_descr *descr,
				   void *obj,
				   struct json_token *tokens,
				   size_t tokens_count,
				   size_t *token_idx)
{
	int r;

	switch (descr->type) {
	case JSON_OBJ_TYPE_BOOL:
	{
		bool *val = (bool *)((uint8_t *)obj + descr->offset);

		r = json_next_token(json_string, len, tokens, tokens_count,
				    token_idx);
		if (r < 0) {
			return r;
		}

		if (tokens[*token_idx].type == JSON_TOK_TRUE) {
			*val = true;
		} else if (tokens[*token_idx].type == JSON_TOK_FALSE) {
			*val = false;
		} else {
			return -EINVAL;
		}

		(*token_idx)++;
		return 0;
	}

	case JSON_OBJ_TYPE_STRING:
	{
		const char **str_ptr = (const char **)obj;
		char *buf = (char *)obj;
		size_t max_len = descr->size;

		r = json_next_token(json_string, len, tokens, tokens_count,
				    token_idx);
		if (r < 0) {
			return r;
		}

		if (tokens[*token_idx].type != JSON_TOK_STRING) {
			return -EINVAL;
		}

		if (max_len == 0) {
			*str_ptr = tokens[*token_idx].ptr;
		} else {
			if (tokens[*token_idx].len >= max_len) {
				return -ENOMEM;
			}

			memcpy(buf, tokens[*token_idx].ptr, tokens[*token_idx].len);
			buf[tokens[*token_idx].len] = '
';
		}

		(*token_idx)++;
		return 0;
	}

	case JSON_OBJ_TYPE_INT:
	{
		int64_t *val = (int64_t *)((uint8_t *)obj + descr->offset);

		r = json_next_token(json_string, len, tokens, tokens_count,
				    token_idx);
		if (r < 0) {
			return r;
		}

		if (tokens[*token_idx].type != JSON_TOK_NUMBER) {
			return -EINVAL;
		}

		r = json_token_to_int(json_string, &tokens[*token_idx], val);
		if (r < 0) {
			return r;
		}

		(*token_idx)++;
		return 0;
	}

	case JSON_OBJ_TYPE_ARRAY:
	{
		const struct json_obj_descr *array_descr = descr->obj_descr;
		void *array_data = (uint8_t *)obj + descr->offset;
		size_t *array_count = (size_t *)((uint8_t *)obj + descr->offset +
						 sizeof(void *));
		size_t max_elements = descr->size;

		r = json_next_token(json_string, len, tokens, tokens_count,
				    token_idx);
		if (r < 0) {
			return r;
		}

		if (tokens[*token_idx].type != JSON_TOK_ARRAY_START) {
			return -EINVAL;
		}

		(*token_idx)++;

		*array_count = 0;

		while (true) {
			r = json_next_token(json_string, len, tokens, tokens_count,
					    token_idx);
			if (r < 0) {
				return r;
			}

			if (tokens[*token_idx].type == JSON_TOK_ARRAY_END) {
				break;
			}

			if (*array_count >= max_elements) {
				return -ENOMEM;
			}

			size_t element_stride;
			if (array_descr->type == JSON_OBJ_TYPE_STRING) {
				element_stride = sizeof(const char *);
			} else {
				element_stride = array_descr->size;
			}

			int ret = json_obj_parse_internal(json_string, len, array_descr,
							  (uint8_t *)array_data +
							  (*array_count) * element_stride,
							  tokens, tokens_count, token_idx);
			if (ret < 0) {
				return ret;
			}

			(*array_count)++;

			r = json_next_token(json_string, len, tokens, tokens_count,
					    token_idx);
			if (r < 0) {
				return r;
			}

			if (tokens[*token_idx].type == JSON_TOK_COMMA) {
				(*token_idx)++;
			} else if (tokens[*token_idx].type == JSON_TOK_ARRAY_END) {
				break;
			} else {
				return -EINVAL;
			}
		}

		(*token_idx)++;
		return 0;
	}

	case JSON_OBJ_TYPE_OBJECT:
	{
		const struct json_obj_descr *member_descr = descr->obj_descr;
		size_t member_count = descr->size;
		bool *parsed_members = alloca(member_count);
		bool member_found;

		(void)memset(parsed_members, 0, member_count);

		r = json_next_token(json_string, len, tokens, tokens_count,
				    token_idx);
		if (r < 0) {
			return r;
		}

		if (tokens[*token_idx].type != JSON_TOK_OBJECT_START) {
			return -EINVAL;
		}

		(*token_idx)++;

		while (true) {
			r = json_next_token(json_string, len, tokens, tokens_count,
					    token_idx);
			if (r < 0) {
				return r;
			}

			if (tokens[*token_idx].type == JSON_TOK_OBJECT_END) {
				break;
			}

			if (tokens[*token_idx].type != JSON_TOK_STRING) {
				return -EINVAL;
			}

			member_found = false;
			for (size_t i = 0; i < member_count; i++) {
				if (json_token_is_string(json_string, &tokens[*token_idx],
							 member_descr[i].field_name)) {
					parsed_members[i] = true;
					member_found = true;
					(*token_idx)++;

					r = json_next_token(json_string, len, tokens, tokens_count,
							    token_idx);
					if (r < 0) {
						return r;
					}

					if (tokens[*token_idx].type != JSON_TOK_COLON) {
						return -EINVAL;
					}

					(*token_idx)++;

					int ret = json_obj_parse_internal(json_string, len,
								  &member_descr[i].obj_descr,
								  (uint8_t *)obj + member_descr[i].offset,
								  tokens, tokens_count, token_idx);
					if (ret < 0) {
						return ret;
					}

					break;
				}
			}

			if (!member_found) {
				/* Unknown member, skip value */
				(*token_idx)++;

				r = json_next_token(json_string, len, tokens, tokens_count,
						    token_idx);
				if (r < 0) {
					return r;
				}

				if (tokens[*token_idx].type != JSON_TOK_COLON) {
					return -EINVAL;
				}

				(*token_idx)++;

				r = json_skip_value(json_string, len, tokens, tokens_count,
						    token_idx);
				if (r < 0) {
					return r;
				}
			}

			r = json_next_token(json_string, len, tokens, tokens_count,
					    token_idx);
			if (r < 0) {
				return r;
			}

			if (tokens[*token_idx].type == JSON_TOK_COMMA) {
				(*token_idx)++;
			} else if (tokens[*token_idx].type == JSON_TOK_OBJECT_END) {
				break;
			} else {
				return -EINVAL;
			}
		}

		(*token_idx)++;

		for (size_t i = 0; i < member_count; i++) {
			if (!parsed_members[i] && member_descr[i].req) {
				return -EINVAL;
			}
		}

		return 0;
	}

	default:
		return -EINVAL;
	}
}

int json_obj_parse(const char *json_string, size_t len,
		   const struct json_obj_descr *descr,
		   size_t descr_len, void *obj)
{
	size_t token_idx = 0;

	return json_obj_parse_internal(json_string, len,
				       &(const struct json_obj_descr) {
					.type = JSON_OBJ_TYPE_OBJECT,
					.offset = 0,
					.size = descr_len,
					.obj_descr = descr,
				       },
				       obj, tokens, CONFIG_JSON_TOKEN_COUNT, &token_idx);
}

static int json_obj_encode_internal(json_append_handler_t handler,
				    void *handler_context,
				    const struct json_obj_descr *descr,
				    const void *obj)
{
	int r;

	switch (descr->type) {
	case JSON_OBJ_TYPE_BOOL:
	{
		const bool *val = (const bool *)((uint8_t *)obj + descr->offset);

		r = json_append_bool(handler, handler_context, *val);
		if (r < 0) {
			return r;
		}

		return 0;
	}

	case JSON_OBJ_TYPE_STRING:
	{
		const char * const *str_ptr = (const char * const *)obj;
		const char *buf = (const char *)obj;
		size_t max_len = descr->size;

		if (max_len == 0) {
			r = json_append_string(handler, handler_context, *str_ptr);
		} else {
			r = json_append_string(handler, handler_context, buf);
		}

		if (r < 0) {
			return r;
		}

		return 0;
	}

	case JSON_OBJ_TYPE_INT:
	{
		const int64_t *val = (const int64_t *)((uint8_t *)obj + descr->offset);

		r = json_append_int(handler, handler_context, *val);
		if (r < 0) {
			return r;
		}

		return 0;
	}

	case JSON_OBJ_TYPE_ARRAY:
	{
		const struct json_obj_descr *array_descr = descr->obj_descr;
		const void *array_data = (uint8_t *)obj + descr->offset;
		const size_t *array_count = (const size_t *)((uint8_t *)obj +
							 descr->offset + sizeof(void *));

		r = json_append_array_start(handler, handler_context);
		if (r < 0) {
			return r;
		}

		for (size_t i = 0; i < *array_count; i++) {
			size_t element_stride;
			if (array_descr->type == JSON_OBJ_TYPE_STRING) {
				element_stride = sizeof(const char *);
			} else {
				element_stride = array_descr->size;
			}

			r = json_obj_encode_internal(handler, handler_context, array_descr,
						     (uint8_t *)array_data + i * element_stride);
			if (r < 0) {
				return r;
			}

			if (i < (*array_count - 1)) {
				r = json_append_comma(handler, handler_context);
				if (r < 0) {
					return r;
				}
			}
		}

		r = json_append_array_end(handler, handler_context);
		if (r < 0) {
			return r;
		}

		return 0;
	}

	case JSON_OBJ_TYPE_OBJECT:
	{
		const struct json_obj_descr *member_descr = descr->obj_descr;
		size_t member_count = descr->size;
		bool first_member = true;

		r = json_append_object_start(handler, handler_context);
		if (r < 0) {
			return r;
		}

		for (size_t i = 0; i < member_count; i++) {
			bool skip = false;

			if (member_descr[i].req) {
				switch (member_descr[i].obj_descr.type) {
				case JSON_OBJ_TYPE_BOOL:
					/* Booleans are always initialized to false, so we can't
					 * tell if they were set or not.
					 */
					break;

				case JSON_OBJ_TYPE_STRING:
				{
					const char * const *str_ptr = (const char * const *)((uint8_t *)obj +
											 member_descr[i].offset);
					const char *buf = (const char *)((uint8_t *)obj +
										 member_descr[i].offset);

					if (member_descr[i].obj_descr.size == 0) {
						if (*str_ptr == NULL) {
							skip = true;
						}
					} else {
						if (buf[0] == '
') {
							skip = true;
						}
					}
					break;
				}

				case JSON_OBJ_TYPE_INT:
					/* Integers are always initialized to 0, so we can't
					 * tell if they were set or not.
					 */
					break;

				case JSON_OBJ_TYPE_ARRAY:
				{
					const size_t *array_count = (const size_t *)((uint8_t *)obj +
											 member_descr[i].offset +
											 sizeof(void *));
					if (*array_count == 0) {
						skip = true;
					}
					break;
				}

				case JSON_OBJ_TYPE_OBJECT:
					/* Objects are always initialized, so we can't tell if
					 * they were set or not.
					 */
					break;

				default:
					return -EINVAL;
				}
			}

			if (skip) {
				continue;
			}

			if (!first_member) {
				r = json_append_comma(handler, handler_context);
				if (r < 0) {
					return r;
				}
			}

			r = json_append_member_name(handler, handler_context,
						member_descr[i].field_name);
			if (r < 0) {
				return r;
			}

			r = json_obj_encode_internal(handler, handler_context,
						 &member_descr[i].obj_descr,
						 (uint8_t *)obj + member_descr[i].offset);
			if (r < 0) {
				return r;
			}

			first_member = false;
		}

		r = json_append_object_end(handler, handler_context);
		if (r < 0) {
			return r;
		}

		return 0;
	}

	default:
		return -EINVAL;
	}
}

int json_obj_encode(json_append_handler_t handler,
		    void *handler_context,
		    const struct json_obj_descr *descr,
		    size_t descr_len, const void *obj)
{
	return json_obj_encode_internal(handler, handler_context,
					&(const struct json_obj_descr) {
						.type = JSON_OBJ_TYPE_OBJECT,
						.offset = 0,
						.size = descr_len,
						.obj_descr = descr,
					},
					obj);
}
